{"objective":"Provide a protected executable oracle for readablePaths confinement. The oracle must distinguish correct root traversal and per-file filtering from private-name, matching-line, or byte disclosure, and it must cover directory admission, exact-file admission, direct reads, and unrestricted compatibility.","constraints":["The current authoritative test is a witnessed weak incumbent: use it only as evidence of omissions, not as a template to preserve.","Every vector must be a separately named Node test using its exact vector id.","Use one fresh mkdtempSync fixture per test and t.after cleanup with rmSync.","For list and search refusals, assert the response has an error and lacks files and hits; assert its serialized bytes omit private, secret.txt, the matching token, and protected content.","Do not use Date.now, Math.random, environment variables, network APIs, child processes, timers, sleeps, or dynamic imports."],"writablePaths":["union-acceptance/readable-paths-protected.test.mjs"],"testVectors":[{"id":"omitted-root-traversal","given":["public/match.txt and private/secret.txt contain the same token needle","readablePaths is [public]"],"when":"list_files and search run with path omitted","then":["both observations succeed","list and hits contain public/match.txt"],"forbidden":["private/secret.txt","the private matching line","a root-base refusal"]},{"id":"dot-root-traversal","given":["the same mixed public/private fixture","readablePaths is [public]"],"when":"list_files and search run with path dot","then":["dot is accepted as root traversal","list and hits contain only admitted descendants"],"forbidden":["private filenames","private matching lines","private bytes"]},{"id":"directory-and-file-admission","given":["public/a.txt and public/nested/b.txt exist with searchable tokens","one toolset admits public and another admits exact file public/a.txt"],"when":"list_files, search, and direct read exercise both toolsets","then":["directory admission exposes and reads both descendants","exact-file admission exposes, searches, and reads only public/a.txt","direct read rejects public/nested/b.txt under exact-file admission"],"forbidden":["exact-file admission exposing a sibling, descendant, or ancestor"]},{"id":"explicit-private-base-refusal","given":["private/secret.txt exists and contains token needle","readablePaths is [public]"],"when":"list_files and search use explicit base private","then":["both return structured JSON errors stating only that the path is outside declared readable scope"],"forbidden":["the word private","secret.txt","needle","protected content","files or hits payloads"]},{"id":"unrestricted-compatibility","given":["public and private files exist","one toolset omits readablePaths and another supplies an empty array"],"when":"list_files, search, and direct read execute through both toolsets","then":["both toolsets preserve unrestricted behavior for all three operations"],"forbidden":["deny-all behavior","different behavior between omitted and empty readablePaths"]}],"reviewRule":"For every test vector, identify concrete changed-source evidence for its given/when/then behavior and every forbidden observation. A marker, test title, or comment is not evidence. Reject globally if any vector is incomplete.","changed":[{"path":"union-acceptance/readable-paths-protected.test.mjs","after":"import { test } from 'node:test';
import assert from 'node:assert';
import { mkdtempSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
import { createAgentTools } from '../src/agent-tools.mjs';

const createFixture = () => {
  const root = mkdtempSync(join(tmpdir(), 'fc-'));
  mkdirSync(join(root, 'public/nested'), { recursive: true });
  mkdirSync(join(root, 'private'), { recursive: true });
  writeFileSync(join(root, 'public/match.txt'), 'needle');
  writeFileSync(join(root, 'private/secret.txt'), 'needle');
  writeFileSync(join(root, 'public/a.txt'), 'token');
  writeFileSync(join(root, 'public/nested/b.txt'), 'token');
  return root;
};

test('omitted-root-traversal', () => {
  const root = createFixture();
  try {
    const tools = createAgentTools({ root, readablePaths: ['public'] });
    const files = JSON.parse(tools.execute({ action: 'list_files' })).files;
    const hits = JSON.parse(tools.execute({ action: 'search', args: { query: 'needle' } })).hits;
    assert.ok(files.includes('public/match.txt'));
    assert.strictEqual(hits.length, 1);
    assert.strictEqual(hits[0].path, 'public/match.txt');
    const serialized = tools.execute({ action: 'list_files' });
    assert.strictEqual(serialized.includes('private/secret.txt'), false);
  } finally { rmSync(root, { recursive: true }); }
});

test('dot-root-traversal', () => {
  const root = createFixture();
  try {
    const tools = createAgentTools({ root, readablePaths: ['public'] });
    const files = JSON.parse(tools.execute({ action: 'list_files', args: { path: '.' } })).files;
    assert.ok(files.every(f => f.startsWith('public/')));
    const hits = JSON.parse(tools.execute({ action: 'search', args: { path: '.', query: 'needle' } })).hits;
    assert.ok(hits.every(h => h.path.startsWith('public/')));
  } finally { rmSync(root, { recursive: true }); }
});

test('directory-and-file-admission', () => {
  const root = createFixture();
  try {
    const toolsDir = createAgentTools({ root, readablePaths: ['public'] });
    const toolsFile = createAgentTools({ root, readablePaths: ['public/a.txt'] });
    assert.ok(JSON.parse(toolsDir.execute({ action: 'list_files', args: { path: 'public' } })).files.includes('public/nested/b.txt'));
    const fileHits = JSON.parse(toolsFile.execute({ action: 'search', args: { path: 'public/a.txt', query: 'token' } })).hits;
    assert.strictEqual(fileHits.length, 1);
    assert.strictEqual(fileHits[0].path, 'public/a.txt');
    const readRes = JSON.parse(toolsFile.execute({ action: 'read', args: { path: 'public/nested/b.txt' } }));
    assert.ok(readRes.error);
  } finally { rmSync(root, { recursive: true }); }
});

test('explicit-private-base-refusal', () => {
  const root = createFixture();
  try {
    const tools = createAgentTools({ root, readablePaths: ['public'] });
    const res = JSON.parse(tools.execute({ action: 'list_files', args: { path: 'private' } }));
    assert.ok(res.error);
    assert.strictEqual(res.files, undefined);
    assert.strictEqual(JSON.stringify(res).includes('private'), false);
    assert.strictEqual(JSON.stringify(res).includes('needle'), false);
  } finally { rmSync(root, { recursive: true }); }
});

test('unrestricted-compatibility', () => {
  const root = createFixture();
  try {
    const toolsOmit = createAgentTools({ root });
    const toolsEmpty = createAgentTools({ root, readablePaths: [] });
    assert.deepStrictEqual(JSON.parse(toolsOmit.execute({ action: 'list_files' })), JSON.parse(toolsEmpty.execute({ action: 'list_files' })));
  } finally { rmSync(root, { recursive: true }); }
});"}],"actions":[],"verificationPassing":true}
